const D=DashboardData, app=document.getElementById('app');
let period={start:D.latest,end:D.latest,mode:'single'}, route={id:null,market:null}, sortKey='value', sort='desc', returnFocus=null, countTrend='storeCount', queryFocus=null;
const monthLabel=i=>D.monthKey(i).replace('-','年')+'月';
const rangeLabel=p=>p.start===p.end?monthLabel(p.start):`${monthLabel(p.start)} — ${monthLabel(p.end)}`;
const periodText=()=>rangeLabel(period);
function rateArrow(id,v){if(!['cagr','growth'].includes(id)||v===null||!Number.isFinite(v)||Math.round(v*10)===0)return '';return `<svg class="rate-arrow ${v>0?'up':'down'}" viewBox="0 0 20 20" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${v>0?'M2 15 8 9 12 13 18 5M12 5h6v6':'M2 5 8 11 12 7 18 15M12 15h6V9'}"/></svg>`}
const sign=(v,unit='%',id)=>{if(v===null)return '—';const rounded=Math.round(v*10)/10;return `${rounded>0?'+':''}${rounded.toFixed(1)}${unit}${rateArrow(id,v)}`};
const tone=v=>v===null?'':Math.round(v*10)===0?'neutral':v>0?'up':'down';
const display=(id,v)=>{const f=D.format(id,v),content=`<span class="metric-digits notranslate" translate="no" role="img" aria-label="${f.number}" data-number="${f.number}"></span><small>${f.unit}</small>`;return ['cagr','growth'].includes(id)?`<span class="rate-value ${v===null||Math.round(v*10)===0?'':tone(v)}">${content}${rateArrow(id,v)}</span>`:content};
const tableValue=(id,v)=>{const number=D.format(id,v).number;return ['cagr','growth'].includes(id)?`<span class="rate-value table-rate ${v===null||Math.round(v*10)===0?'':tone(v)}">${number}${rateArrow(id,v)}</span>`:number};
const textValue=(id,v)=>{const f=D.format(id,v);return f.number+f.unit};
const icon='<svg viewBox="0 0 32 32" fill="none" stroke="currentColor" stroke-width="1.8"><rect x="10" y="4" width="13" height="24" rx="2"/><path d="M10 15H5v13h23V13h-5M14 10h5m-5 6h5m-5 6h5"/></svg>';
const visibleMarkets=()=>D.markets;
const selectedStores=(market,id=route.id)=>D.select(market,id);
const totalLabel=()=>'集团合计';
function href(id=null,market=null,p=period){const path=id?`metric/${id}${market?'/'+market:''}`:'home';return `#/${path}?start=${D.monthKey(p.start)}&end=${D.monthKey(p.end)}&mode=${p.mode}`}
const isAnnual=mode=>mode==='annual'||mode==='annualRange';
function annualPeriod(year,endYear=year,mode='annual'){if(year>endYear||endYear>Math.floor(D.latest/12))return null;const start=year*12,end=Math.min(endYear*12+11,D.latest);return D.validPeriod(start,end)?{start,end,mode}:null}
function defaultPeriod(mode){if(isAnnual(mode))return annualPeriod(Math.max(Math.floor(D.earliest/12),Math.floor((D.latest+1)/12)-1),Math.floor(D.latest/12),'annualRange');const end=D.latest,start=mode==='range'?Math.floor((end+1)/12)*12:end;return start<=end?{start,end,mode}:null}
function readRoute(){
  const [path,query='']=location.hash.replace(/^#\/?/,'').split('?'),parts=path.split('/'),q=new URLSearchParams(query);
  const requested=q.get('mode'),mode=requested==='annual'?'annualRange':['single','range','annualRange'].includes(requested)?requested:'single';
  const defaults=defaultPeriod(mode)||defaultPeriod('single');
  const start=D.monthIndex(q.get('start')||D.monthKey(defaults.start)),end=D.monthIndex(q.get('end')||D.monthKey(defaults.end));
  period=isAnnual(mode)?(annualPeriod(Math.floor(start/12),mode==='annualRange'?Math.floor(end/12):Math.floor(start/12),mode)||defaultPeriod(mode)):D.validPeriod(start,end)?{start,end,mode:mode==='range'||start!==end?'range':'single'}:defaultPeriod('single');
  route={id:parts[0]==='metric'&&D.metrics[parts[1]]?parts[1]:null,market:visibleMarkets().some(m=>m.id===parts[2])?parts[2]:null};
}
function dateSelect(endpoint,value,label){
  const annual=isAnnual(period.mode),first=annual?Math.floor(D.earliest/12):D.earliest,last=annual?Math.floor(D.latest/12):D.latest;
  return `<label class="quick-date"><span>${label}</span><select id="query-${endpoint}" data-endpoint="${endpoint}" aria-label="${label}">${Array.from({length:last-first+1},(_,i)=>{const v=last-i;return `<option value="${v}" ${v===value?'selected':''}>${annual?v+'年':D.monthKey(v)}</option>`}).join('')}</select></label>`;
}
function header(){
  const annual=isAnnual(period.mode),single=period.mode==='single',defaults=defaultPeriod(period.mode),atDefault=defaults&&period.start===defaults.start&&period.end===defaults.end;
  const dates=single?`<button id="query-prev" class="month-step" aria-label="上一个月" ${period.end<=D.earliest?'disabled':''}>‹</button>${dateSelect('end',period.end,'统计月份')}<button id="query-next" class="month-step" aria-label="下一个月" ${period.end>=D.latest?'disabled':''}>›</button>`:`${dateSelect('start',annual?Math.floor(period.start/12):period.start,annual?'开始年度':'开始月份')}<span class="range-to">至</span>${dateSelect('end',annual?Math.floor(period.end/12):period.end,annual?'结束年度':'结束月份')}`;
  return `<header class="hero"><div class="hero-top"><div class="brand"><span class="brand-icon">${icon}</span><h1>集团看板</h1></div><span class="demo">DEMO</span></div></header><section class="query-panel" aria-label="查询条件"><div class="mode-switch" role="group" aria-label="查询方式">${[['single','单月'],['range','月度累计'],['annualRange','年度累计']].map(([mode,label])=>`<button id="mode-${mode}" data-mode="${mode}" aria-pressed="${period.mode===mode}" ${defaultPeriod(mode)?'':'disabled title="当年暂无已结束月份"'}>${label}</button>`).join('')}</div><div class="quick-dates">${dates}</div><div class="query-help"><span>选后即更新 · 数据截至 ${D.monthKey(D.latest)}</span><button id="query-reset" ${atDefault||!defaults?'disabled':''}>恢复默认</button></div></section>`;
}
function infoButton(id){return `<button class="info" data-info="${id}" aria-label="${D.metrics[id].group} ${D.metrics[id].name}指标口径" translate="no"><svg viewBox="0 0 20 20" fill="none" stroke="currentColor" stroke-width="1.3" aria-hidden="true" focusable="false"><circle cx="10" cy="10" r="7"/><path d="M10 9v5"/><circle cx="10" cy="6.5" r=".8" fill="currentColor" stroke="none"/></svg></button>`}
function comparisonRow(c){const points=c.unit==='个百分点',unit=points?'':c.unit;return `${points?'<span class="comparison-unit" translate="no">同环比单位：百分点</span>':''}<span class="comparison-row" translate="no"><span class="metric-compare">环比 <b class="${tone(c.mom)}">${sign(c.mom,unit)}</b></span><span class="metric-compare">同比 <b class="${tone(c.yoy)}">${sign(c.yoy,unit)}</b></span></span>`}
function metricTile(id){const m=D.metrics[id],c=D.comparisons(id,selectedStores(null,id),period);return `<article class="metric-tile"><div class="metric-heading"><span>${m.name}</span>${infoButton(id)}</div><a class="metric-link" href="${href(id)}" aria-label="${m.group} ${m.name}，${textValue(id,c.value)}，查看市场"><div class="number">${display(id,c.value)}</div><p class="metric-caption">${m.caption}</p>${comparisonRow(c)}</a></article>`}
const groupIcons={
  'IPO 数据':'<path d="M4 3v17h17"/><rect x="7" y="12" width="3" height="5" rx=".6"/><rect x="12" y="8" width="3" height="9" rx=".6"/><rect x="17" y="4" width="3" height="13" rx=".6"/>',
  '管理数据':'<rect x="5" y="4" width="14" height="17" rx="2"/><rect x="9" y="2" width="6" height="4" rx="1" fill="#edf4ff"/><path d="m8 11 1 1 2-2m2 1h3m-8 5 1 1 2-2m2 1h3"/>',
  '经营中心':'<path d="M4 10v10h16V10M3 7l2-4h14l2 4v2a3 3 0 0 1-6 0 3 3 0 0 1-6 0 3 3 0 0 1-6 0V7Z"/><path d="M3 7h18M9 7V3m6 4V3m-1 17v-6h-4v6"/>'
};
function groupCard(g){return `<section class="card metric-panel"><div class="card-heading"><h3><span class="mini-icon" aria-hidden="true"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" focusable="false">${groupIcons[g.name]}</svg></span>${g.name}</h3></div><div class="metric-grid ${g.ids.length===6?'six':''}">${g.ids.map(metricTile).join('')}</div></section>`}
function sectionTitle(no,title,desc=''){return `<div class="section-title"><h2>${title}</h2>${desc?`<small>${desc}</small>`:''}</div>`}
function placeholder(title,note){return `<div class="placeholder"><div><h3>${title}</h3><p>${note}</p></div><span class="reserved">预留</span></div>`}
function home(){return `<main class="home-content">${sectionTitle('01','经营指标')}<div class="operating-grid">${D.groups.slice(0,2).map(groupCard).join('')}</div>${sectionTitle('02','业务板块')}${groupCard(D.groups[2])}<div class="placeholder-grid">${placeholder('市场营销','本期暂不开发')}${placeholder('人力板块','指标待补充')}</div><div class="reserved-grid"><section>${sectionTitle('03','资金看板')}${placeholder('集团资金看板','本期暂不开发')}</section><section>${sectionTitle('04','集团会员')}${placeholder('集团会员','本期暂不开发')}</section></div></main>`}
function breadcrumb(){const m=D.metrics[route.id],market=D.markets.find(x=>x.id===route.market);return `<nav class="breadcrumb" aria-label="页面路径"><a class="back-link" href="${market?href(route.id):href()}" aria-label="${market?'返回市场':'返回集团'}">‹ ${market?'返回市场':'返回集团'}</a><a href="${href()}">集团首页</a><span>/</span>${market?`<a href="${href(route.id)}">${m.name} · 市场</a><span>/</span><span>${market.name}</span>`:`<span>${m.name} · 市场</span>`}</nav>`}
function summary(id,stores,label,title){const m=D.metrics[id],c=D.comparisons(id,stores,period);return `<section class="card summary-card"><div class="card-heading"><h3>${title||label+' · '+m.name}</h3>${infoButton(id)}</div><div class="summary-body"><p class="caption">${m.caption}</p><div class="summary-number">${display(id,c.value)}</div>${comparisonRow(c)}</div></section>`}
function trend(id,stores){
  const annual=isAnnual(period.mode),len=D.metrics[id].type==='count'?1:period.end-period.start+1,firstYear=Math.floor((period.mode==='annualRange'?period.start:D.earliest)/12),lastYear=Math.floor(period.end/12);
  const points=annual?Array.from({length:lastYear-firstYear+1},(_,i)=>{const year=firstYear+i,p=annualPeriod(year);return {start:p.start,end:p.end,tick:year+'年',label:year+'年'+(p.end%12<11?'（1–'+(p.end%12+1)+'月）':'')}}):Array.from({length:12},(_,i)=>{const end=period.end-11+i;return {start:end-len+1,end,tick:(end%12+1)+'月',label:monthLabel(end)+(len>1?' · 滚动'+len+'个月':'')}});
  const vals=points.map(p=>D.value(id,stores,p)),valid=vals.filter(v=>v!==null),m=D.metrics[id],factor=m.type==='money'?10000:1,title=annual?'年度趋势':'近 12 个月趋势',hitWidth=annual?40:255/11;
  let min=Math.min(0,...valid)/factor,max=Math.max(0,...valid)/factor;if(max===min)max=min+1;const pad=(max-min)*.13;max+=pad;if(min<0)min-=pad;if(m.type==='count')max=Math.max(2,Math.ceil(max/2)*2);
  const coords=vals.map((v,i)=>({x:points.length===1?181.5:54+i*255/(points.length-1),y:v===null?null:154-(v/factor-min)/(max-min)*124}));
  let path='',inLine=false;coords.forEach(p=>{if(p.y===null){inLine=false;return}path+=`${inLine?'L':'M'}${p.x} ${p.y} `;inLine=true});
  const tick=v=>m.type==='count'?v.toFixed(0):Math.abs(v)>=10000?(v/10000).toFixed(1)+'万':Math.abs(v)>=1000?Math.round(v).toLocaleString('zh-CN'):v.toFixed(Math.abs(v)<10?1:0);
  return `<section class="card trend-card"><div class="card-heading"><h3>${title}</h3><span class="caption">${annual?'按年度':len>1?'滚动 '+len+' 个月':'按单月'} · ${D.format(id,0).unit}</span></div><div class="chart-container"><svg viewBox="0 0 340 204" role="group" aria-label="${m.name}${annual?'年度趋势':'近12个月趋势'}">${[0,1,2].map(i=>`<line x1="54" x2="312" y1="${30+i*62}" y2="${30+i*62}" stroke="#e9eff8" stroke-dasharray="3 3"/><text x="45" y="${34+i*62}" text-anchor="end">${tick(max-(max-min)*i/2)}</text>`).join('')}<path d="${path}" fill="none" stroke="#3370ff" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"/>${coords.map((p,i)=>`${p.y===null?'':`<circle data-point="${i}" cx="${p.x}" cy="${p.y}" r="3.5" stroke="#3370ff" stroke-width="2" fill="white"/>`}<text class="${annual?'year-tick':'month-tick'}" x="${p.x}" y="176" text-anchor="${annual?'middle':'end'}"${annual?'':` transform="rotate(-45 ${p.x} 176)"`}>${points[i].tick}</text>`).join('')}${coords.map((p,i)=>`<rect class="trend-hit" data-trend-hit="${i}" data-x="${p.x}" data-y="${p.y??90}" data-label="${points[i].label}" data-value="${textValue(id,vals[i])}" x="${p.x-hitWidth/2}" y="22" width="${hitWidth}" height="136" fill="transparent" tabindex="0" role="button" aria-label="${points[i].label}，${textValue(id,vals[i])}"/>`).join('')}<line class="trend-guide" x1="0" x2="0" y1="22" y2="154" stroke="#91caff" stroke-dasharray="3 3" visibility="hidden"/><g class="trend-tooltip" visibility="hidden" aria-hidden="true"><rect width="184" height="48" rx="7"/><text class="tooltip-month" x="10" y="18"></text><text class="tooltip-value" x="10" y="37"></text></g></svg></div></section>`
}
function showTrendValue(target){
  const svg=target.closest('svg'),tip=svg.querySelector('.trend-tooltip'),x=Number(target.dataset.x),y=Number(target.dataset.y);
  svg.querySelectorAll('[data-point]').forEach(dot=>{const active=dot.dataset.point===target.dataset.trendHit;dot.setAttribute('r',active?'5':'3.5');dot.setAttribute('fill',active?'#3370ff':'white')});
  const guide=svg.querySelector('.trend-guide');guide.setAttribute('x1',x);guide.setAttribute('x2',x);guide.setAttribute('visibility','visible');
  tip.querySelector('.tooltip-month').textContent=target.dataset.label;
  tip.querySelector('.tooltip-value').textContent=target.dataset.value;
  tip.setAttribute('transform',`translate(${Math.max(4,Math.min(152,x-92))} ${y>82?y-60:y+12})`);
  tip.setAttribute('visibility','visible');tip.setAttribute('aria-hidden','false');
}
const countIds=['storeCount','storeOpened','storeClosed'],countNames=['在营门店数量','新开门店数量','闭店门店数量'];
function countAnalysis(){
  const market=D.markets.find(m=>m.id===route.market),selected=selectedStores(route.market),title=market?market.name+' · 门店数':'门店数 · 市场';
  const comparisonCells=stores=>countIds.map(id=>{const c=D.comparisons(id,stores,period);return `<td>${D.format(id,c.value).number}</td><td class="${tone(c.mom)}">${sign(c.mom)}</td><td class="${tone(c.yoy)}">${sign(c.yoy)}</td>`}).join('');
  const table=market?`<section class="card"><div class="card-heading"><h3>门店明细</h3></div><div class="table-wrap"><table class="store-lifecycle-table"><thead><tr><th>门店</th><th>期末状态</th><th>开业月份</th><th>闭店月份</th><th>本期新开</th><th>本期闭店</th></tr></thead><tbody>${selected.map(s=>{const c=D.storeCounts([s],period);return `<tr><td><span class="store-name">${s.name}</span></td><td>${s.opened>period.end?'未开业':c.storeCount?'在营':'已闭店'}</td><td>${D.monthKey(s.opened)}</td><td>${s.closed!=null&&s.closed<=period.end?D.monthKey(s.closed):'—'}</td><td>${c.storeOpened?'是':'—'}</td><td>${c.storeClosed?'是':'—'}</td></tr>`}).join('')}</tbody></table></div></section>`:`<section class="card"><div class="card-heading"><h3>市场对比</h3><span class="caption">单位：家</span></div><div class="table-wrap"><table class="store-count-table"><thead><tr><th rowspan="2">市场</th>${countNames.map(name=>`<th colspan="3">${name}</th>`).join('')}</tr><tr>${countIds.map(()=>'<th>本期</th><th>环比</th><th>同比</th>').join('')}</tr></thead><tbody>${visibleMarkets().map(m=>`<tr><td><a class="market-row" href="${href('storeCount',m.id)}">${m.name}</a></td>${comparisonCells(selectedStores(m.id))}</tr>`).join('')}<tr class="total"><td>${totalLabel()}</td>${comparisonCells(selectedStores())}</tr></tbody></table></div></section>`;
  return `<main class="detail-content">${breadcrumb()}<div class="page-heading"><h2>${title}</h2><span class="level-tag">${market?'门店':'市场'}</span></div><div class="store-count-summary">${countIds.map((id,i)=>summary(id,selected,'',countNames[i])).join('')}</div><div class="count-trend-tabs" role="group" aria-label="门店趋势指标">${countIds.map((id,i)=>`<button data-count-trend="${id}" aria-pressed="${countTrend===id}">${countNames[i]}</button>`).join('')}</div>${trend(countTrend,selected)}${table}</main>`;
}
function marketAnalysis(){const id=route.id,m=D.metrics[id],dualCompare=(['IPO 数据','管理数据','经营中心'].includes(m.group)),comparisonUnit=m.type==='percent'?'百分点':'%',rows=visibleMarkets().map(x=>({...x,c:D.comparisons(id,selectedStores(x.id),period)}));return `<main class="detail-content">${breadcrumb()}<div class="page-heading"><div><h2>${m.name} · 市场</h2></div><span class="level-tag">市场</span></div><div class="analysis-grid">${summary(id,selectedStores(),'集团')}${trend(id,selectedStores())}</div><section class="card markets-card"><div class="card-heading"><h3>市场对比</h3><span class="caption">单位：${D.format(id,0).unit}</span></div><div class="table-wrap"><table${dualCompare?' class="management-table"':''}><thead><tr><th>市场</th><th>${period.mode==='annualRange'?'累计':period.mode==='annual'?'本年':'本期'}</th><th>${dualCompare?'环比（'+comparisonUnit+'）':m.type==='percent'?'较上期变化':'环比'}</th>${dualCompare?'<th>同比（'+comparisonUnit+'）</th>':''}</tr></thead><tbody>${rows.map(r=>`<tr><td><a class="market-row" href="${href(id,r.id)}">${r.name}</a></td><td><a class="market-value" href="${href(id,r.id)}" aria-label="${r.name} ${m.name}，查看门店">${tableValue(id,r.c.value)}</a></td><td class="${tone(r.c.mom)}">${sign(r.c.mom,dualCompare?'':m.type==='percent'?'百分点':'%',id)}</td>${dualCompare?`<td class="${tone(r.c.yoy)}">${sign(r.c.yoy,'',id)}</td>`:''}</tr>`).join('')}<tr class="total"><td>${totalLabel()}</td><td>${tableValue(id,D.value(id,selectedStores(),period))}</td><td class="${tone(D.comparisons(id,selectedStores(),period).mom)}">${sign(D.comparisons(id,selectedStores(),period).mom,dualCompare?'':m.type==='percent'?'百分点':'%',id)}</td>${dualCompare?`<td class="${tone(D.comparisons(id,selectedStores(),period).yoy)}">${sign(D.comparisons(id,selectedStores(),period).yoy,'',id)}</td>`:''}</tr></tbody></table></div></section></main>`}
function sortHeading(key,label){return `<th aria-sort="${sortKey===key?(sort==='asc'?'ascending':'descending'):'none'}"><button class="column-sort" data-sort="${key}" aria-label="${label}，点击按数值${sortKey===key&&sort==='asc'?'降序':'升序'}排序">${label}<span aria-hidden="true">${sortKey===key?(sort==='asc'?'↑':'↓'):'↕'}</span></button></th>`}
function storesAnalysis(){
  const id=route.id,m=D.metrics[id],dualCompare=(['IPO 数据','管理数据','经营中心'].includes(m.group)),comparisonUnit=m.type==='percent'?'百分点':'%',market=D.markets.find(x=>x.id===route.market),selected=selectedStores(route.market),rows=selected.map(s=>({...s,c:D.comparisons(id,[s],period)})).sort((a,b)=>{const av=a.c[sortKey],bv=b.c[sortKey];return av===null?(bv===null?0:1):bv===null?-1:(sort==='desc'?-1:1)*(av-bv)});
  return `<main class="detail-content">${breadcrumb()}<div class="page-heading"><div><h2>${market.name} · ${m.name}</h2></div><span class="level-tag">门店</span></div><div class="analysis-grid">${summary(id,selected,market.name)}${trend(id,selected)}</div><section class="card store-card"><div class="card-heading"><h3>门店明细</h3><span class="caption">单位：${D.format(id,0).unit}</span></div><div class="table-wrap"><table${dualCompare?' class="management-table"':''}><thead><tr><th>门店</th>${sortHeading('value',period.mode==='annualRange'?'累计':period.mode==='annual'?'本年':'本期')}${sortHeading('mom',dualCompare?'环比（'+comparisonUnit+'）':m.type==='percent'?'较上期变化':'环比')}${dualCompare?sortHeading('yoy','同比（'+comparisonUnit+'）'):''}</tr></thead><tbody>${rows.map(s=>`<tr><td><span class="store-name">${s.name}</span></td><td>${tableValue(id,s.c.value)}</td><td class="${tone(s.c.mom)}">${sign(s.c.mom,dualCompare?'':m.type==='percent'?'百分点':'%',id)}</td>${dualCompare?`<td class="${tone(s.c.yoy)}">${sign(s.c.yoy,'',id)}</td>`:''}</tr>`).join('')}<tr class="total"><td>市场汇总</td><td>${tableValue(id,D.value(id,selected,period))}</td><td class="${tone(D.comparisons(id,selected,period).mom)}">${sign(D.comparisons(id,selected,period).mom,dualCompare?'':m.type==='percent'?'百分点':'%',id)}</td>${dualCompare?`<td class="${tone(D.comparisons(id,selected,period).yoy)}">${sign(D.comparisons(id,selected,period).yoy,'',id)}</td>`:''}</tr></tbody></table></div></section></main>`
}
function render(){readRoute();app.className='notranslate '+(route.id?'detail-view':'home-view');app.innerHTML=header()+(route.id?(route.id==='storeCount'?countAnalysis():route.market?storesAnalysis():marketAnalysis()):home())+'<footer>全部为模拟数据 · 未连接业务系统<br>集团 / 市场 / 门店口径一致</footer>';document.title=(route.id?D.metrics[route.id].name+(route.market?' · 门店明细':' · 市场'):'集团看板')+' · 移动端 Demo';bind()}
function bind(){
  document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{if(b.dataset.mode!==period.mode)applyPeriod(defaultPeriod(b.dataset.mode),b.id)});
  document.querySelectorAll('[data-endpoint]').forEach(s=>s.onchange=()=>changeDate(s.dataset.endpoint,Number(s.value),s.id));
  document.getElementById('query-reset').onclick=()=>applyPeriod(defaultPeriod(period.mode),'query-reset');
  if(period.mode==='single')for(const [id,delta] of [['query-prev',-1],['query-next',1]])document.getElementById(id).onclick=()=>changeDate('end',period.end+delta,id);
  if(queryFocus){document.getElementById(queryFocus)?.focus?.({preventScroll:true});queryFocus=null;}
  document.querySelectorAll('[data-info]').forEach(b=>b.onclick=()=>openInfo(b.dataset.info,b));
  document.querySelectorAll('[data-trend-hit]').forEach(target=>{target.onclick=()=>showTrendValue(target);target.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();showTrendValue(target)}}});
  document.querySelectorAll('[data-count-trend]').forEach(b=>b.onclick=()=>{const y=scrollY;countTrend=b.dataset.countTrend;render();scrollTo(0,y);document.querySelector(`[data-count-trend="${countTrend}"]`).focus({preventScroll:true})});
  document.querySelectorAll('[data-sort]').forEach(b=>b.onclick=()=>{const y=scrollY,key=b.dataset.sort;sort=sortKey===key&&sort==='asc'?'desc':'asc';sortKey=key;render();scrollTo(0,y);document.querySelector(`[data-sort="${key}"]`).focus({preventScroll:true})});
}
const dialog=document.getElementById('sheet');
function showDialog(content,title,focus){dialog.className='notranslate';returnFocus=focus||document.activeElement;dialog.innerHTML=`<div class="sheet-handle"></div><div class="sheet-head"><h2 id="sheet-title">${title}</h2><button type="button" class="close" aria-label="关闭" translate="no"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" aria-hidden="true" focusable="false"><path d="m6 6 12 12M18 6 6 18"/></svg></button></div>${content}`;dialog.querySelector('.close').onclick=()=>dialog.close();dialog.showModal()}
dialog.addEventListener('close',()=>{if(returnFocus?.isConnected)returnFocus.focus()});dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});
function openInfo(id,focus){const m=D.metrics[id];showDialog(`<span class="sheet-tag">${m.group}</span><h3 class="formula-label">${m.caption}</h3><p class="formula">${m.formula}</p>${m.note?`<p class="sheet-note">${m.note}</p>`:''}${m.type==='percent'?'<p class="sheet-note">同比、环比为本期比率与比较期比率的差值，单位统一为百分点。</p>':''}<h3 class="formula-label">数据来源</h3><p class="sheet-note">${m.source}</p><p class="demo-note">当前为模拟数据，未连接业务系统。</p>`,m.name+' · 指标说明',focus)}
function changeDate(endpoint,value,focusId){
  const annual=isAnnual(period.mode),min=annual?Math.floor(D.earliest/12):D.earliest,max=annual?Math.floor(D.latest/12):D.latest;
  if(!Number.isInteger(value)||value<min||value>max)return;
  let start=annual?Math.floor(period.start/12):period.start,end=annual?Math.floor(period.end/12):period.end;
  if(period.mode==='single')start=end=value;
  else if(endpoint==='start'){start=value;end=Math.max(end,start)}else{end=value;start=Math.min(start,end)}
  applyPeriod(annual?annualPeriod(start,end,'annualRange'):{start,end,mode:period.mode},focusId);
}
function applyPeriod(p,focusId){if(!p||!D.validPeriod(p.start,p.end))return;queryFocus=focusId;const next=href(route.id,route.market,p);if(location.hash===next){period=p;render()}else location.hash=next}
window.addEventListener('hashchange',()=>{render();scrollTo(0,0)});render();
